from gradio_client import Client
c = Client("mteb/leaderboard")
import mteb
b = mteb.get_benchmark('MTEB(Scandinavian, v1)')
tasks = [t.metadata.name for t in b.tasks]
# collect all langs from tasks
langs = set()
for t in b.tasks:
    if hasattr(t.metadata, 'eval_langs'):
        el = t.metadata.eval_langs
        if isinstance(el, list):
            for x in el:
                # format like 'eng-Latn'
                if isinstance(x, str):
                    langs.add(x.split('-')[0])
        elif isinstance(el, dict):
            for k, v in el.items():
                for x in v:
                    langs.add(x.split('-')[0])
print("tasks:", len(tasks), "langs:", len(langs))
# Try update_tables
try:
    r = c.predict(tasks=tasks, languages=list(langs), api_name="/update_tables")
    print("type:", type(r), "len:", len(r) if hasattr(r,'__len__') else 'na')
    # r is tuple of tables; pick the first
    import json
    for i, x in enumerate(r):
        print(f"--- table {i} ---")
        if isinstance(x, dict):
            print(list(x.keys())[:10])
            print(str(x)[:500])
except Exception as e:
    print("err:", e)
